def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([0]), fmt([-3]), fmt([2, 3, -2, 4]), fmt([-2, 0, -1]), fmt([-2, 3, -4, -1, 2]),
             fmt([0, 0, 0]), fmt([-1, -1]), fmt([-2, -3, -4]), fmt([5, 0, 6, -1, 7]), fmt([10, -10, 10, -10, 10])]
    for n in (2, 3, 4, 5, 6, 7, 8):
        for _ in range(3):
            tests.append(fmt([rng.randint(-10, 10) for _ in range(n)]))
    for _ in range(6):
        tests.append(fmt([rng.choice([-2, -1, 0, 1, 2]) for _ in range(rng.randint(5, 14))]))
    n = 100000
    # large cases: +-1 with a few +-2 and zeros so every subarray product stays small
    def sparse(zero_rate, twos):
        a = [rng.choice([-1, 1]) for _ in range(n)]
        for i in range(n):
            if rng.random() < zero_rate:
                a[i] = 0
        for i in rng.sample(range(n), twos):
            a[i] = rng.choice([-2, 2])
        return a
    tests.append(fmt(sparse(0.0, 18)))
    tests.append(fmt(sparse(0.0005, 18)))
    tests.append(fmt([-1] * (n - 1) + [1]))
    tests.append(fmt([-1] * n))
    return tests
